<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- formatFeticheBerryStatHintHtml builds spans from numeric stats */
  import { miltankFarm } from '../stores/miltankFarm.svelte.ts';
  import { ui as modalUi } from '../stores/ui.svelte.ts';
  import { miltankFarmTooltipHandlers, touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import { game } from '../../gameManager.ts';
  import { formatFeticheBerryStatHintHtml } from '../../constants/balance/feticheBerries.ts';
  import {
    buildBerryTreeBerryTooltipContent,
    type FeticheBerryTooltipUi,
  } from '../lib/feticheBerryTooltip.ts';
  import type { BerryTreeAlmanacEntrySnapshot, BerryTreeMulchOptionSnapshot, BerryTreePlantOptionSnapshot } from '../bus/snapshots.js';

  let snap = $derived(miltankFarm.snapshot);
  let bt = $derived(snap.berryTree);
  let ui = $derived(bt.ui);
  let activeTab = $state<'discover' | 'almanac' | 'tree'>('discover');
  let pickerSlotIndex = $state<number | null>(null);
  let pickerQuery = $state('');
  let berryModalWasOpen = false;
  let queueDraftMode = $derived(bt.combineInProgress && bt.showCombinePickerDuringProgress);
  let draftSlotsEditable = $derived(!bt.combineInProgress || bt.showCombinePickerDuringProgress);

  $effect(() => {
    if (!draftSlotsEditable) pickerSlotIndex = null;
  });

  $effect(() => {
    const open = modalUi.openModals.has('berryTreeModal');
    if (open && !berryModalWasOpen) {
      activeTab = bt.unlockedCount > 0 ? 'tree' : 'discover';
    }
    berryModalWasOpen = open;
  });

  function openPicker(slotIndex: number) {
    if (!draftSlotsEditable) return;
    pickerSlotIndex = slotIndex;
  }

  function closePicker() {
    pickerSlotIndex = null;
    pickerQuery = '';
  }

  /** Keep picker open and advance to the next empty slot (skip the slot just filled). */
  function afterPickSlot() {
    if (pickerSlotIndex === null) return;
    const current = pickerSlotIndex;
    const nextEmpty = bt.combineDraft.findIndex((s, i) => i !== current && !s.itemKey);
    pickerSlotIndex = nextEmpty >= 0 ? nextEmpty : null;
  }

  let queueRemainingSlots = $derived(
    bt.combineQueueLevel > 0
      ? Math.max(0, bt.combineMaxInFlight - bt.combineInFlightCount)
      : 0,
  );

  let plantQueueRemainingSlots = $derived(
    bt.plantQueueLevel > 0
      ? Math.max(0, bt.plantQueueLevel - bt.plantQueuePreview.length)
      : 0,
  );

  function purchaseCombineQueueUpgrade() {
    game?.purchaseBerryCombineQueueUpgrade();
  }

  function purchasePlantQueueUpgrade() {
    game?.purchaseBerryPlantQueueUpgrade();
  }

  const TASTE_MARK: Record<string, string> = {
    loved: '♥♥',
    liked: '♥',
    neutral: '–',
    disliked: '✕',
    hated: '✕✕',
  };

  function tasteMark(taste: string | null): string | null {
    if (!taste) return null;
    return TASTE_MARK[taste] ?? null;
  }

  function tasteLabel(taste: string | null): string | null {
    if (!taste) return null;
    const labels: Record<string, string> = {
      loved: ui.tasteLoved,
      liked: ui.tasteLiked,
      neutral: ui.tasteNeutral,
      disliked: ui.tasteDisliked,
      hated: ui.tasteHated,
    };
    return labels[taste] ?? null;
  }

  function itemTip(title: string, body = '') {
    if (!title) return {};
    return touchTooltipHandlers(() => ({ title, body }));
  }

  function revealedHintCount(entry: BerryTreeAlmanacEntrySnapshot): number {
    return entry.recipeSlots.filter((slot) => slot.revealed).length;
  }

  function oneHintLeft(entry: BerryTreeAlmanacEntrySnapshot): boolean {
    const total = entry.recipeSlots.length;
    const revealed = revealedHintCount(entry);
    return total > 0 && revealed === total - 1;
  }

  let tasteLegend = $derived([
    { taste: 'loved', mark: '♥♥', label: ui.tasteLoved },
    { taste: 'liked', mark: '♥', label: ui.tasteLiked },
    { taste: 'neutral', mark: '–', label: ui.tasteNeutral },
    { taste: 'disliked', mark: '✕', label: ui.tasteDisliked },
    { taste: 'hated', mark: '✕✕', label: ui.tasteHated },
  ]);

  function almanacGroup(entry: BerryTreeAlmanacEntrySnapshot): 'progress' | 'unlocked' | 'other' {
    if (entry.unlocked) return 'unlocked';
    const revealed = revealedHintCount(entry);
    const total = entry.recipeSlots.length;
    if (revealed > 0 && revealed < total) return 'progress';
    return 'other';
  }

  let almanacSorted = $derived.by(() => {
    const rank = { progress: 0, unlocked: 1, other: 2 } as const;
    return [...bt.almanacEntries].sort((a, b) => {
      const groupDiff = rank[almanacGroup(a)] - rank[almanacGroup(b)];
      if (groupDiff !== 0) return groupDiff;
      if (almanacGroup(a) !== 'progress') return 0;
      const missingA = a.recipeSlots.length - revealedHintCount(a);
      const missingB = b.recipeSlots.length - revealedHintCount(b);
      return missingA - missingB;
    });
  });

  let visibleHistory = $derived(
    bt.lastCombineResult
      ? bt.combineHistory.filter((entry) => entry.timestamp !== bt.lastCombineResult?.timestamp)
      : bt.combineHistory,
  );

  function almanacSectionLabel(group: 'progress' | 'unlocked' | 'other'): string {
    if (group === 'progress') return ui.almanacInProgress;
    if (group === 'unlocked') return ui.almanacUnlocked;
    return ui.almanacOther;
  }

  function useKnownHints(entry: BerryTreeAlmanacEntrySnapshot): void {
    const slots = [0, 1, 2].map((index) => {
      const slot = entry.recipeSlots[index];
      return slot?.revealed && slot.itemKey ? slot.itemKey : '';
    });
    game?.loadBerryCombineDraft(slots.join(':'));
    activeTab = 'discover';
    closePicker();
  }

  let pickerQueryNormalized = $derived(pickerQuery.trim().toLocaleLowerCase());
  let filteredItemGroups = $derived.by(() => {
    if (!pickerQueryNormalized) return bt.combineEligibleItemGroups;
    return bt.combineEligibleItemGroups
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => item.displayName.toLocaleLowerCase().includes(pickerQueryNormalized)),
      }))
      .filter((group) => group.items.length > 0);
  });

  function draftHasItem(itemKey: string): boolean {
    return bt.combineDraft.some((slot) => slot.itemKey === itemKey);
  }

  let harvestReady = $derived(bt.canClaim || !!bt.activeCrop?.productionComplete);
  let analysisReady = $derived(!!bt.lastCombineResult);

  const tasteUi = $derived({
    tasteLoved: ui.tasteLoved,
    tasteLiked: ui.tasteLiked,
    tasteNeutral: ui.tasteNeutral,
    tasteDisliked: ui.tasteDisliked,
    tasteHated: ui.tasteHated,
    tasteCombatHint: ui.tasteCombatHint,
  } satisfies FeticheBerryTooltipUi);

  function berryTooltipHandlers(
    entry: Pick<
      BerryTreeAlmanacEntrySnapshot | BerryTreePlantOptionSnapshot,
      'feticheTaste' | 'feticheStatEffect' | 'berryDescription'
    > & { name: string },
  ) {
    return miltankFarmTooltipHandlers(() => {
      const content = buildBerryTreeBerryTooltipContent(
        {
          name: entry.name,
          feticheTaste: entry.feticheTaste,
          feticheStatEffect: entry.feticheStatEffect,
          description: entry.berryDescription,
        },
        tasteUi,
      );
      return content ?? { title: entry.name, body: '' };
    });
  }

  function mulchTooltipHandlers(mulch: BerryTreeMulchOptionSnapshot) {
    return miltankFarmTooltipHandlers(() => ({
      title: mulch.tooltipTitle,
      body: mulch.tooltipBody,
    }));
  }

  function statHintHtml(
    effect: BerryTreeAlmanacEntrySnapshot['feticheStatEffect'],
  ): string {
    if (!effect) return '';
    return formatFeticheBerryStatHintHtml(effect);
  }
</script>

<div
  class="stats-content berry-tree-modal-content miltank-farm-modal-shell"
  data-action="stopPropagation"
  data-action-stop
>
  <div class="stats-header">
    <h2 id="berryTreeTitleLabel">{ui.title}</h2>
    <button type="button" class="stats-close" data-action="closeBerryTreeModal">&#10005;</button>
  </div>

  <div class="berry-tree-tabs" role="tablist">
    <button
      type="button"
      id="berryTreeTreeTab"
      class="berry-tree-tab"
      class:active={activeTab === 'tree'}
      role="tab"
      aria-selected={activeTab === 'tree'}
