          <div class="berry-tree-combine-slots berry-tree-combine-slots-pending">
            {#each bt.combinePendingSlots as slot (slot.slotIndex)}
              <div class="berry-tree-combine-slot" class:is-filled={!!slot.itemKey}>
                <span class="berry-tree-slot-lock" aria-hidden="true">🔒</span>
                <span class="berry-tree-slot-label">{slot.slotIndex + 1}</span>
                {#if slot.itemIconUrl}
                  <img class="berry-tree-slot-img" src={slot.itemIconUrl} alt="" width="32" height="32" />
                  <span class="berry-tree-slot-name">{slot.itemName}</span>
                {:else}
                  <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                {/if}
              </div>
            {/each}
          </div>
          <div class="berry-tree-combine-progress-card">
            <div class="berry-tree-combine-progress-head">
              <p class="berry-tree-combine-progress-label">{bt.combineProgressLabel}</p>
              <span class="berry-tree-combine-progress-pct" aria-hidden="true">{bt.combineRemainingLabel ? `${bt.combineRemainingLabel} · ` : ''}{bt.combineProgressPct}%</span>
            </div>
            <div
              class="miltank-farm-bar berry-tree-combine-progress-bar"
              role="progressbar"
              aria-valuenow={bt.combineProgressPct}
              aria-valuemin="0"
              aria-valuemax="100"
              aria-label="{bt.combineProgressLabel ?? ui.combineProgress} — {bt.combineRemainingLabel ?? ''} {bt.combineProgressPct}%"
            >
              <div class="miltank-farm-bar-fill" style="width: {bt.combineProgressPct}%"></div>
            </div>
          </div>
        </div>

        <div class="berry-tree-combine-discover-section">
          <h3 class="berry-tree-subtitle">{ui.combineQueueDraftTitle}</h3>
          <p class="berry-tree-hint">{ui.combineQueueDraftHint}</p>
          <div class="berry-tree-combine-slots">
            {#each bt.combineDraft as slot (slot.slotIndex)}
              <button
