              <span>⚠️ {ui.alreadyAttemptedWarn}</span>
            </div>
          {/if}
          {#if bt.draftCostLabel}
            <p class="berry-tree-draft-cost-hint">{bt.draftCostLabel}</p>
          {/if}
          <div class="berry-tree-combine-actions">
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--feed"
              data-action="tryBerryTreeCombination"
              disabled={!bt.canTryCombine}
            >{!bt.canTryCombine && bt.tryDisabledReason ? bt.tryDisabledReason : ui.queueCombineBtn}</button>
            <button type="button" class="miltank-farm-btn miltank-farm-btn--reroll" data-action="clearBerryCombineDraft">
              {ui.clearBtn}
            </button>
          </div>
        </div>
      {:else}
        <div class="berry-tree-combine-discover-section" class:is-analyzing={bt.combineInProgress}>
          <h3 class="berry-tree-subtitle">{ui.combineDiscoverTitle}</h3>
          <p class="berry-tree-hint">{draftSlotsEditable ? ui.pickItem : ui.tryBtnInProgress}</p>
          <div class="berry-tree-combine-slots" class:berry-tree-combine-slots-pending={bt.combineInProgress}>
            {#each (bt.combineInProgress ? bt.combinePendingSlots : bt.combineDraft) as slot (slot.slotIndex)}
              {#if draftSlotsEditable}
                <button
                  type="button"
                  class="berry-tree-combine-slot"
