                          <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                        {/if}
                        {#if slot.itemName}
                          <span class="berry-tree-combine-queue-preview-name">{slot.itemName}</span>
                        {/if}
                      </div>
                    {/each}
                  </div>
                </div>
              {/each}
              {#each Array(queueRemainingSlots) as _, emptyIndex (`empty-${emptyIndex}`)}
                <div class="berry-tree-combine-queue-preview-row berry-tree-combine-queue-preview-row--empty">
                  <span class="berry-tree-combine-queue-preview-index">{bt.combineQueuePreview.length + emptyIndex + 1}</span>
                  <div class="berry-tree-combine-slots berry-tree-combine-slots--compact">
                    {#each [0, 1, 2] as slotIndex (slotIndex)}
                      <div class="berry-tree-combine-slot">
                        <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                      </div>
                    {/each}
                  </div>
                </div>
              {/each}
            </div>
          {:else}
            <p class="berry-tree-hint">{ui.combineQueueEmptyHint}</p>
          {/if}
        </div>
      {/if}

      {#if bt.combineQueueUpgradeLabel && bt.combineQueueLevel < bt.combineQueueMaxLevel}
        <div class="berry-tree-queue-upgrade-card" class:berry-tree-queue-upgrade-card--locked={!!bt.combineQueueChecks}>
          <h3 class="berry-tree-subtitle">{bt.combineQueueUpgradeLabel}</h3>
          {#if !bt.combineQueueChecks}
            <p class="berry-tree-hint">{ui.combineQueueUpgradeDesc}</p>
            {#if bt.combineQueueUpgradeCostLabel}
              <p class="berry-tree-queue-upgrade-cost">{bt.combineQueueUpgradeCostLabel}</p>
            {/if}
          {/if}
          {#if bt.combineQueueChecks}
            <p class="berry-tree-queue-reqs">
              <span class="berry-tree-req" class:is-met={bt.combineQueueChecks.farmMet}>
                <span class="berry-tree-req-token" aria-hidden="true">{bt.combineQueueChecks.farmMet ? '✓' : '✕'}</span>
                {bt.combineQueueChecks.farmLabel}
              </span>
              <span class="berry-tree-req" class:is-met={bt.combineQueueChecks.milkMet}>
                <span class="berry-tree-req-token" aria-hidden="true">{bt.combineQueueChecks.milkMet ? '✓' : '✕'}</span>
                {bt.combineQueueChecks.milkLabel}
              </span>
            </p>
          {/if}
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--reroll"
            onclick={purchaseCombineQueueUpgrade}
            disabled={!bt.canPurchaseCombineQueueUpgrade}
            title={bt.combineQueueChecks ? ui.combineQueueUpgradeDesc : undefined}
          >{ui.combineQueueUpgradeBtn}</button>
        </div>
      {/if}

      <div class="berry-tree-history-section">
        <div class="berry-tree-history-head">
          <h3 class="berry-tree-subtitle">{ui.historyTitle}</h3>
        </div>
        {#if visibleHistory.length > 0}
          <div class="berry-tree-history-list">
            {#each visibleHistory as entry, i (`${entry.timestamp}-${i}`)}
              <div class="berry-tree-history-row" class:success={entry.success}>
                <div class="berry-tree-history-slots">
                  {#each entry.submittedSlots as slot (slot.slotIndex)}
                    {#if slot.itemIconUrl}
                      <img
                        src={slot.itemIconUrl}
                        alt={slot.itemName ?? ''}
                        class="berry-tree-history-img"
                        width="22"
                        height="22"
                        {...itemTip(slot.itemName ?? '')}
                      />
                    {:else}
                      <span class="berry-tree-mini-slot-empty">?</span>
                    {/if}
                  {/each}
                </div>
                <div class="berry-tree-history-outcome">
                  <span
                    class="berry-tree-history-badge"
                    class:badge-unlocked={entry.outcomeType === 'unlocked'}
                    class:badge-revealed={entry.outcomeType === 'revealed'}
                    class:badge-none={entry.outcomeType === 'none'}
                  >
                    {entry.outcomeLabel}
                  </span>
                </div>
                <div class="berry-tree-history-meta">
                  <span class="berry-tree-history-time">{entry.timeAgoLabel}</span>
                  {#if draftSlotsEditable}
                    <button
                      type="button"
                      class="berry-tree-history-reload-btn"
                      data-action="loadBerryCombineDraft"
                      data-arg={entry.serializedArg}
                      title={ui.reloadHistoryBtn}
                    >↺</button>
                  {/if}
                </div>
              </div>
            {/each}
          </div>
        {:else if bt.combineHistory.length === 0}
          <p class="berry-tree-hint">{bt.combineInProgress ? ui.historyPending : ui.historyEmpty}</p>
        {/if}
      </div>
    </section>
  {:else if activeTab === 'almanac'}
    <section class="berry-tree-panel" aria-label={ui.tabAlmanac}>
      <p class="berry-tree-almanac-progress">{bt.almanacProgressLabel}</p>
      {#if bt.feticheTasteHint}
        <p class="berry-tree-fetiche-taste-hint">{bt.feticheTasteHint}</p>
        <p class="berry-tree-taste-legend">
          {#each tasteLegend as item (item.taste)}
            <span class="berry-tree-taste-legend-item">
              <span class="berry-tree-fetiche-taste fetiche-taste-{item.taste}">{item.mark}</span>
              {item.label}
            </span>
          {/each}
        </p>
      {/if}
      <div class="berry-tree-almanac-grid">
        {#each almanacSorted as entry, almanacIndex (entry.berryKey)}
          {#if almanacIndex === 0 || almanacGroup(entry) !== almanacGroup(almanacSorted[almanacIndex - 1])}
            <h3 class="berry-tree-almanac-section">{almanacSectionLabel(almanacGroup(entry))}</h3>
          {/if}
          {#if entry.canPlant}
            <div
              class="berry-tree-almanac-card plantable unlocked miltank-farm-tooltip-host"
              data-tooltip-variant="miltank-farm"
              {...berryTooltipHandlers(entry)}
            >
              <div class="berry-tree-almanac-head">
                {#if entry.canQueue || entry.isQueued}
                  <button
                    type="button"
                    class="berry-tree-almanac-berry-queue-btn"
                    class:queued={entry.isQueued}
                    data-action="setBerryPlantQueue"
                    data-arg={entry.berryKey}
                    title={ui.queueBerryBtn}
                    disabled={!entry.canQueue}
                  >
                    {#if entry.berryIconUrl}
                      <img src={entry.berryIconUrl} alt="" class="berry-tree-almanac-berry-img" width="28" height="28" />
                    {/if}
                  </button>
                {:else if entry.berryIconUrl}
                  <img src={entry.berryIconUrl} alt="" class="berry-tree-almanac-berry-img" width="28" height="28" />
                {/if}
                <h3 class="berry-tree-almanac-name">{entry.name}</h3>
                <span class="berry-tree-unlocked-badge">{ui.unlockedBadge}</span>
                {#if entry.isActiveCrop}
                  <span class="berry-tree-active-crop-badge">{ui.productionLabel}</span>
                {/if}
                {#if entry.feticheTaste && tasteMark(entry.feticheTaste)}
                  <span class="berry-tree-fetiche-taste fetiche-taste-{entry.feticheTaste}" title={tasteLabel(entry.feticheTaste) ?? ''}>
                    {tasteMark(entry.feticheTaste)}
                  </span>
                {/if}
              </div>
              <button
                type="button"
                class="berry-tree-almanac-plant-trigger"
                data-action="confirmPlantBerryFromDex"
                data-arg={entry.berryKey}
              >
                <div class="berry-tree-recipe-slots">
                  {#each entry.recipeSlots as slot, i (entry.berryKey + '-' + i)}
                    <div class="berry-tree-recipe-slot" class:revealed={slot.revealed}>
                      {#if slot.revealed && slot.itemIconUrl}
                        <img
                          src={slot.itemIconUrl}
                          alt=""
                          width="24"
                          height="24"
                          {...itemTip(slot.itemName ?? '', slot.itemDescription ?? '')}
                        />
                      {:else}
                        <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                      {/if}
                    </div>
                  {/each}
                </div>
              </button>
            </div>
          {:else}
          <article
            class="berry-tree-almanac-card miltank-farm-tooltip-host"
            data-tooltip-variant="miltank-farm"
            {...berryTooltipHandlers(entry)}
          >
            <div class="berry-tree-almanac-head">
              {#if entry.berryIconUrl}
                <img src={entry.berryIconUrl} alt="" class="berry-tree-almanac-berry-img" width="28" height="28" />
              {/if}
              <h3 class="berry-tree-almanac-name">{entry.name}</h3>
              {#if almanacGroup(entry) === 'progress'}
                <span class="berry-tree-hint-fraction">{revealedHintCount(entry)}/{entry.recipeSlots.length}</span>
              {/if}
              {#if entry.feticheTaste && tasteMark(entry.feticheTaste)}
                <span class="berry-tree-fetiche-taste fetiche-taste-{entry.feticheTaste}" title={tasteLabel(entry.feticheTaste) ?? ''}>
                  {tasteMark(entry.feticheTaste)}
                </span>
              {/if}
            </div>
            <div class="berry-tree-recipe-slots">
              {#each entry.recipeSlots as slot, i (entry.berryKey + '-' + i)}
                <div class="berry-tree-recipe-slot" class:revealed={slot.revealed}>
                  {#if slot.revealed && slot.itemIconUrl}
                    <img
                      src={slot.itemIconUrl}
                      alt=""
                      width="24"
                      height="24"
                      {...itemTip(slot.itemName ?? '', slot.itemDescription ?? '')}
                    />
                  {:else}
                    <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                  {/if}
                </div>
              {/each}
            </div>
            {#if revealedHintCount(entry) > 0}
              <button
                type="button"
                class="miltank-farm-btn berry-tree-hints-btn"
                class:miltank-farm-btn--feed={oneHintLeft(entry)}
                class:miltank-farm-btn--reroll={!oneHintLeft(entry)}
                onclick={() => useKnownHints(entry)}
              >{ui.useHintsBtn}</button>
            {/if}
          </article>
          {/if}
        {/each}
      </div>
    </section>
  {:else}
    <section class="berry-tree-panel" aria-label={ui.tabTree}>
      {#if bt.fertilizerActive && bt.boostRemainingLabel}
        <p class="berry-tree-boost-label">{bt.boostRemainingLabel}</p>
      {/if}
      {#if bt.fertilizerActive && bt.boostEffectDetailLabel}
        <p class="berry-tree-boost-detail">{bt.boostEffectDetailLabel}</p>
      {/if}
      {#if bt.activeCrop}
        <div class="berry-tree-crop-card">
          <div class="berry-tree-crop-head">
            {#if bt.activeCrop.berryIconUrl}
              <img src={bt.activeCrop.berryIconUrl} alt="" width="40" height="40" />
            {/if}
            <div>
              <strong>{bt.activeCrop.berryName}</strong>
              <p>{ui.productionLabel}: {bt.activeCrop.productionRateLabel}</p>
              <p>{ui.stockLabel}: {bt.activeCrop.storedQty}/{bt.activeCrop.stockCap}</p>
            </div>
          </div>
          <div class="berry-tree-combine-progress-card berry-tree-production-progress-card">
            <div class="berry-tree-combine-progress-head">
              <p
                class="berry-tree-combine-progress-label berry-tree-production-eta"
                class:berry-tree-production-done={!!bt.activeCrop.productionDoneLabel}
              >
                {bt.activeCrop.productionDoneLabel ?? bt.activeCrop.productionEtaLabel ?? ui.productionLabel}
              </p>
              <span class="berry-tree-combine-progress-pct" aria-hidden="true">{bt.activeCrop.fillPct}%</span>
            </div>
            <div
              class="miltank-farm-bar berry-tree-combine-progress-bar"
              role="progressbar"
              aria-valuenow={bt.activeCrop.fillPct}
              aria-valuemin="0"
              aria-valuemax="100"
              aria-label="{(bt.activeCrop.productionDoneLabel ?? bt.activeCrop.productionEtaLabel ?? ui.productionLabel)} — {bt.activeCrop.fillPct}%"
            >
              <div class="miltank-farm-bar-fill" style="width: {bt.activeCrop.fillPct}%"></div>
            </div>
          </div>
          <div class="berry-tree-crop-actions">
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--claim"
              data-action="claimBerryTreeHarvest"
              disabled={!bt.activeCrop.canClaim}
            >{ui.claimBtn}</button>
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--reroll"
              data-action="cancelBerryTreeCrop"
            >{ui.cancelCropBtn}</button>
          </div>
        </div>
      {:else}
        <div class="berry-tree-crop-card">
          <div class="berry-tree-crop-head">
            <div>
              <strong>{ui.treeIdle}</strong>
              {#if bt.unlockedCount === 0}
                <p class="berry-tree-empty">{ui.noBerryWelcome}</p>
              {:else}
                <p class="berry-tree-empty">{ui.noCrop}</p>
              {/if}
            </div>
          </div>
          {#if bt.unlockedCount === 0}
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--feed"
              onclick={() => { activeTab = 'discover'; }}
            >{ui.discoverBerryBtn}</button>
          {/if}
        </div>
      {/if}

      {#if bt.unlockedCount > 0}
      <button
        type="button"
        class="miltank-farm-btn miltank-farm-btn--reroll berry-tree-stock-btn"
        data-action="openBagBerriesFromBerryTree"
      >{ui.openBagBerries}</button>
      {/if}

      {#if bt.unlockedCount > 0}
      <h3 class="berry-tree-subtitle">{ui.selectBerry}</h3>
      <div class="berry-tree-plant-grid">
        {#each bt.plantOptions as opt (opt.berryKey)}
          <div class="berry-tree-plant-row">
            <button
              type="button"
              class="berry-tree-plant-btn miltank-farm-tooltip-host"
              class:active={opt.isActive}
              class:queued={opt.isQueued}
              data-action="plantBerryTreeCrop"
              data-arg={opt.berryKey}
              data-tooltip-variant="miltank-farm"
              disabled={opt.isActive || !opt.canAffordIngredients}
              {...berryTooltipHandlers({
                name: opt.displayName,
                feticheTaste: opt.feticheTaste,
                feticheStatEffect: opt.feticheStatEffect,
                berryDescription: opt.berryDescription,
              })}
            >
              {#if opt.iconUrl}
                <img src={opt.iconUrl} alt="" width="24" height="24" />
              {/if}
              <span>{opt.displayName}</span>
              {#if opt.feticheTaste && tasteMark(opt.feticheTaste)}
                <span class="berry-tree-fetiche-taste fetiche-taste-{opt.feticheTaste}" title={tasteLabel(opt.feticheTaste) ?? ''}>{tasteMark(opt.feticheTaste)}</span>
              {/if}
              {#if opt.feticheStatEffect}
                <span class="berry-tree-fetiche-stat-hint">{@html statHintHtml(opt.feticheStatEffect)}</span>
              {/if}
            </button>
            {#if opt.canQueue || opt.isQueued}
              <button
                type="button"
                class="miltank-farm-btn miltank-farm-btn--chip miltank-farm-btn--reroll"
                class:active={opt.isQueued}
                data-action="setBerryPlantQueue"
                data-arg={opt.berryKey}
                title={ui.queueBerryBtn}
                disabled={!opt.canQueue}
              >{ui.queueBerryBtn}{#if opt.queuedCount > 1} ×{opt.queuedCount}{/if}</button>
            {/if}
          </div>
        {/each}
      </div>
      {/if}

      <h3 class="berry-tree-subtitle">{ui.boostActive}</h3>
      <div class="berry-tree-mulch-list">
        {#each bt.mulchOptions as mulch (mulch.mulchKey)}
          <div class="berry-tree-mulch-row">
            <span
              class="berry-tree-mulch-label miltank-farm-tooltip-host"
              data-tooltip-variant="miltank-farm"
              {...mulchTooltipHandlers(mulch)}
            >
              {#if mulch.iconUrl}
                <img src={mulch.iconUrl} alt="" width="24" height="24" />
              {/if}
              <span class="berry-tree-mulch-copy">
                <span>{mulch.displayName} ×{mulch.owned}</span>
                <span class="berry-tree-mulch-effect">{mulch.effectLabel}</span>
                {#if mulch.blockedLabel}
                  <span class="berry-tree-mulch-blocked">{mulch.blockedLabel}</span>
                {/if}
              </span>
            </span>
            <button
              type="button"
              class="miltank-farm-btn miltank-farm-btn--reroll"
              data-action="applyBerryTreeFertilizer"
              data-arg={mulch.mulchKey}
              disabled={!mulch.canApply}
              title={mulch.blockedLabel ?? undefined}
            >{ui.applyMulchBtn}</button>
          </div>
        {/each}
      </div>

      {#if bt.plantQueueLevel > 0}
        <div class="berry-tree-plant-queue-section" aria-label={ui.plantQueueSectionTitle}>
          <h3 class="berry-tree-subtitle">{ui.plantQueueSectionTitle}</h3>
          {#if bt.plantQueueCapacityLabel}
            <p class="berry-tree-combine-queue-capacity">{bt.plantQueueCapacityLabel}</p>
          {/if}
          {#if bt.plantQueuePreview.length > 0}
            <div class="berry-tree-plant-queue-preview">
              {#each bt.plantQueuePreview as entry, queueIndex (`${entry.berryKey}-${queueIndex}`)}
                <div class="berry-tree-plant-queue-preview-row">
                  <span class="berry-tree-combine-queue-preview-index">{queueIndex + 1}</span>
                  <div class="berry-tree-plant-queue-chip">
                    {#if entry.iconUrl}
                      <img src={entry.iconUrl} alt="" width="28" height="28" />
                    {/if}
                    <span class="berry-tree-plant-queue-chip-name">{entry.displayName}</span>
                  </div>
                </div>
              {/each}
              {#each Array(plantQueueRemainingSlots) as _, emptyIndex (`plant-empty-${emptyIndex}`)}
                <div class="berry-tree-plant-queue-preview-row berry-tree-combine-queue-preview-row--empty">
                  <span class="berry-tree-combine-queue-preview-index">{bt.plantQueuePreview.length + emptyIndex + 1}</span>
                  <div class="berry-tree-plant-queue-chip berry-tree-plant-queue-chip--empty">
                    <span class="berry-tree-slot-empty">{ui.slotEmpty}</span>
                  </div>
                </div>
              {/each}
            </div>
          {:else}
            <p class="berry-tree-hint">{ui.plantQueueEmptyHint}</p>
          {/if}
          {#if bt.plantQueueBlockedReason}
            <p class="berry-tree-hint berry-tree-queue-blocked">{bt.plantQueueBlockedReason}</p>
          {/if}
          {#if bt.canPlantFromQueue || bt.plantQueuePreview.length > 0}
            <div class="berry-tree-plant-queue-actions">
              <button
                type="button"
                class="miltank-farm-btn miltank-farm-btn--feed"
                data-action="plantBerryTreeFromQueue"
                disabled={!bt.canPlantFromQueue}
              >{ui.queuePlantBtn}</button>
            </div>
          {/if}
        </div>
      {/if}

      {#if bt.plantQueueUpgradeLabel && bt.plantQueueLevel < bt.plantQueueMaxLevel}
        <div class="berry-tree-queue-upgrade-card" class:berry-tree-queue-upgrade-card--locked={!!bt.plantQueueChecks}>
          <h3 class="berry-tree-subtitle">{bt.plantQueueUpgradeLabel}</h3>
          {#if !bt.plantQueueChecks}
            <p class="berry-tree-hint">{ui.plantQueueUpgradeDesc}</p>
            {#if bt.plantQueueUpgradeCostLabel}
              <p class="berry-tree-queue-upgrade-cost">{bt.plantQueueUpgradeCostLabel}</p>
            {/if}
          {/if}
          {#if bt.plantQueueChecks}
            <p class="berry-tree-queue-reqs">
              <span class="berry-tree-req" class:is-met={bt.plantQueueChecks.farmMet}>
                <span class="berry-tree-req-token" aria-hidden="true">{bt.plantQueueChecks.farmMet ? '✓' : '✕'}</span>
                {bt.plantQueueChecks.farmLabel}
              </span>
              <span class="berry-tree-req" class:is-met={bt.plantQueueChecks.milkMet}>
                <span class="berry-tree-req-token" aria-hidden="true">{bt.plantQueueChecks.milkMet ? '✓' : '✕'}</span>
                {bt.plantQueueChecks.milkLabel}
              </span>
            </p>
          {/if}
          <button
            type="button"
            class="miltank-farm-btn miltank-farm-btn--reroll"
            onclick={purchasePlantQueueUpgrade}
            disabled={!bt.canPurchasePlantQueueUpgrade}
            title={bt.plantQueueChecks ? ui.plantQueueUpgradeDesc : undefined}
          >{ui.plantQueueUpgradeBtn}</button>
        </div>
      {/if}
    </section>
  {/if}
</div>
